using System.IO;
using System.Text.Json;
namespace MRS;
internal sealed record CapCarrier(int Lcn,long Hz,bool Confirmed=false,string Evidence="User entered; not confirmed",int? ColorCode=null);
internal sealed record TrunkProfile(string Id,string Name,string Protocol,long ControlHz,CapCarrier[] Carriers,int? NetworkId=null,int? SiteId=null);
internal sealed record TrunkCall(string Protocol,int Talkgroup,int? Radio,long Hz,int Slot,int? Nac,DateTimeOffset First,DateTimeOffset Seen,string Evidence,int? ColorCode=null);
internal sealed record TrunkEvent(DateTimeOffset Time,string Kind,string Detail,long Hz=0,int? Talkgroup=null,string Receiver="",string Control="",string Label="",int? Radio=null,int? Nac=null,string Protocol="",int? Slot=null,int? ColorCode=null){public string SlotDisplay=>Slot is 1 or 2?Slot.Value.ToString():"";public string ColorCodeDisplay=>ColorCode is >=0 and <=15?ColorCode.Value.ToString():"";public string NacDisplay=>Nac is >=0 and <=0xFFF?$"0x{Nac.Value:X3}":"";public string TimeUtc=>Time.ToString("HH:mm:ss.fff");public string Frequency=>Hz>0?(Hz/1e6).ToString("F6",System.Globalization.CultureInfo.InvariantCulture):"";}
internal sealed class TrunkFollower(string initialProtocol="P25")
{
    internal TrunkProfile Profile{get;private set;}=new("","",initialProtocol,0,[]);internal bool Running{get;private set;}internal long ControlHz{get;private set;}internal TrunkCall? Active{get;private set;}internal string Status{get;private set;}="Stopped";
    internal (int? Network,int? Site) DmrIdentity=>(dmrNetwork,dmrSite);
    internal long ScopeVersion{get;private set;}
    internal bool RequireConfirmations=true;internal double HangSeconds=3,MaximumSeconds=60;internal int? Hold;internal HashSet<int> Allowed=[],Ignored=[];internal Dictionary<int,string> Labels=[];internal readonly Queue<TrunkEvent> Events=[];private readonly Dictionary<string,TrunkCall> available=[];private P25Identity? p25Bound;private int? capCc,dmrNetwork,dmrSite;private int restCandidate,restCount;private DateTimeOffset restAt,nextPrune;private readonly Dictionary<string,(int Count,DateTimeOffset Seen)> candidates=[];
    internal void Log(DateTimeOffset now,string kind,string detail,long hz=0,int? tg=null,int? slot=null,int? cc=null,int? radio=null,int? nac=null){if(Events.Count>=300)Events.Dequeue();Events.Enqueue(new(now,kind,detail,hz,tg,Radio:radio,Nac:nac,Protocol:Profile.Protocol,Slot:slot is 1 or 2?slot:null,ColorCode:cc));}
    internal static void Validate(TrunkProfile p){if(p.ControlHz<=0||p.ControlHz>6000000000||p.Protocol is not("P25" or "Capacity Plus" or "Connect Plus" or "DMR Tier III"))throw new IOException("Choose a supported protocol and a valid control/rest frequency.");if(p.NetworkId is <0 or >65535||p.SiteId is <0 or >65535)throw new IOException("Network/site IDs must be between 0 and 65535.");if(p.Carriers.Any(c=>c.ColorCode is <0 or >15))throw new IOException("Carrier color code must be 0–15 or blank.");if(p.Carriers.Length>4094||p.Carriers.Any(c=>c.Lcn<1||c.Lcn>(p.Protocol=="Capacity Plus"?8:p.Protocol=="Connect Plus"?15:4094)||c.Hz<=0||c.Hz>6000000000)||p.Carriers.Select(c=>c.Lcn).Distinct().Count()!=p.Carriers.Length)throw new IOException("Channel map needs unique carrier numbers and valid frequencies (Cap+ 1-8, Con+ 1-15, Tier III 1-4094).");}
    internal void Start(TrunkProfile p,DateTimeOffset now){Validate(p);ScopeVersion++;Profile=p;ControlHz=p.ControlHz;Active=null;Running=true;p25Bound=null;capCc=dmrNetwork=dmrSite=null;restCandidate=restCount=0;candidates.Clear();available.Clear();Status="Monitoring control/rest";Log(now,"Start",$"{p.Name} / {p.Protocol}",ControlHz);}
    internal void Stop(DateTimeOffset now,string reason="Stopped"){Running=false;Active=null;Status=reason;Log(now,"Stop",reason,ControlHz);}
    internal bool AllowsTalkgroup(int tg)=>tg>0&&!Ignored.Contains(tg)&&(!Hold.HasValue||Hold==tg)&&(Allowed.Count==0||Allowed.Contains(tg));
    internal void SkipGroup(int group,DateTimeOffset now){candidates[$"skip:{group}"]=(1,now.AddSeconds(5));if(Active?.Talkgroup==group)Active=null;Status="Returning to control after skip";Log(now,"Skip","Five-second skip",0,group);}
    internal void Skip(DateTimeOffset now){if(Active is {} c)SkipGroup(c.Talkgroup,now);}
    internal TrunkCall[] AvailableCalls(DateTimeOffset now)=>available.Values.Where(c=>(now-c.Seen).TotalSeconds<HangSeconds&&AllowsTalkgroup(c.Talkgroup)&&(!candidates.TryGetValue($"skip:{c.Talkgroup}",out var skip)||now>=skip.Seen)).ToArray();
    internal void ConfirmDmrVoice(int colorCode,uint? source)
    {
        if(Active is not {} call||call.Protocol=="P25"||colorCode is <0 or >15||call.ColorCode.HasValue&&call.ColorCode!=colorCode)return;
        Active=call with{ColorCode=colorCode,Radio=source is <=0xFFFFFF?(int)source.Value:call.Radio};
    }
    internal void RetireAvailable(TrunkCall call)
    {
        string key=$"{call.Protocol}:{call.Hz}:{call.Slot}:{call.Talkgroup}";
        if(available.TryGetValue(key,out var candidate)&&candidate.Nac==call.Nac&&candidate.ColorCode==call.ColorCode)available.Remove(key);
    }
    internal void AssignExternal(TrunkCall call,string source){var now=DateTimeOffset.UtcNow;if(!Running||Profile.Id!=source||Profile.Protocol!=call.Protocol||ControlHz!=call.Hz)Start(new(source,source,call.Protocol,call.Hz,[]),now);Active=call with{First=now,Seen=now};Status="Following assigned voice from "+source;Log(now,"Assigned",$"{source}: {call.Evidence}",call.Hz,call.Talkgroup,call.Slot,call.ColorCode,call.Radio,call.Nac);}
    private void Offer(TrunkCall call,DateTimeOffset now){if(!AllowsTalkgroup(call.Talkgroup))return;if(candidates.TryGetValue($"skip:{call.Talkgroup}",out var skip)&&now<skip.Seen)return;if(available.Count>500)available.Clear();available[$"{call.Protocol}:{call.Hz}:{call.Slot}:{call.Talkgroup}"]=call;if(Active is {} a){if(a.Talkgroup==call.Talkgroup&&a.Hz==call.Hz&&a.Slot==call.Slot)Active=a with{Seen=now,Radio=call.Radio??a.Radio};return;}Active=call;Status="Following "+call.Protocol;Log(now,"Follow",call.Evidence,call.Hz,call.Talkgroup,call.Slot,call.ColorCode,call.Radio,call.Nac);}
    internal void ObserveP25(PacketObservation p,DateTimeOffset now){if(!Running||Profile.Protocol!="P25"||p.FrequencyHz!=ControlHz||!p.IsValidated||!p.Validation.Contains("CRC valid")||p.P25Identity is not {} id)return;
        if(p25Bound is {} old&&(old.Nac!=id.Nac||old.SystemId.HasValue&&id.SystemId.HasValue&&old.SystemId!=id.SystemId||old.Wacn.HasValue&&id.Wacn.HasValue&&old.Wacn!=id.Wacn||old.SiteId.HasValue&&id.SiteId.HasValue&&old.SiteId!=id.SiteId||old.RfssId.HasValue&&id.RfssId.HasValue&&old.RfssId!=id.RfssId)){ScopeVersion++;Active=null;available.Clear();Log(now,"Scope","Serving identity changed; previous call discarded");}p25Bound=id;
        foreach(var g in p.P25Assignments??[]){if(g.Channel.DownlinkHz is not {} hz){Log(now,"Unresolved",g.Channel.Resolution,0,g.TalkgroupId);continue;}if(g.Channel.SlotsPerCarrier!=1){Log(now,"Unsupported","P25 TDMA/unknown channel type; Phase I only",hz,g.TalkgroupId);continue;}if((g.ServiceOptions.GetValueOrDefault()&64)!=0){Log(now,"Encrypted","Grant marked encrypted; not followed",hz,g.TalkgroupId);continue;}Offer(new("P25",g.TalkgroupId,g.SourceRadioId,hz,0,id.Nac,now,now,"CRC-valid grant + received identifier table"),now);}}
    internal void ObserveDmr(DmrObservation o,long frequency,DateTimeOffset now){if(!Running||Profile.Protocol=="P25"||!o.LinkValid||o.SlotCorrections>1)return;Log(now,"DMR evidence",$"{o.SystemType}; CC {o.ColorCode}; slot {o.Slot}; TG {o.Destination}; NET {o.Network}; site {o.Site}; advertised rest {o.RestChannel}; {o.Detail}",frequency,o.Destination is uint t?(int)t:null);
        if(frequency==ControlHz){var expectedCodes=Profile.Carriers.Where(c=>c.Hz==frequency&&c.ColorCode.HasValue).Select(c=>c.ColorCode!.Value).Distinct().ToArray();if(expectedCodes.Length>0&&!expectedCodes.Contains(o.ColorCode)){Stop(now,"Control color code does not match the carrier map; review this profile");return;}if(Profile.NetworkId.HasValue&&o.Network.HasValue&&Profile.NetworkId!=o.Network||Profile.SiteId.HasValue&&o.Site.HasValue&&Profile.SiteId!=o.Site){Stop(now,"Decoded network/site does not match selected profile");return;}if(o.Network.HasValue&&dmrNetwork.HasValue&&o.Network!=dmrNetwork||o.Site.HasValue&&dmrSite.HasValue&&o.Site!=dmrSite){Stop(now,"Decoded network/site changed; review selected profile");return;}dmrNetwork=o.Network??dmrNetwork;dmrSite=o.Site??dmrSite;}
        if(Profile.Protocol is "Connect Plus" or "DMR Tier III"){if(Profile.NetworkId.HasValue&&dmrNetwork!=Profile.NetworkId||Profile.SiteId.HasValue&&dmrSite!=Profile.SiteId){Status="Awaiting decoded network/site match for selected map";return;}
         if(frequency!=ControlHz||o.SystemType!=Profile.Protocol||!o.Group||o.Destination is not uint tg||o.GrantChannel is not int lcn||o.GrantSlot is not(1 or 2))return;
         var carrier=Profile.Carriers.FirstOrDefault(c=>c.Lcn==lcn&&(c.Confirmed||!RequireConfirmations));if(carrier==null){Log(now,"Unresolved",$"Carrier {lcn} needs frequency mapping",0,(int)tg);return;}
         string k=$"{lcn}:{o.GrantSlot}:{tg}";int count=candidates.TryGetValue(k,out var prior)&&(now-prior.Seen).TotalSeconds<=2?prior.Count+1:1;candidates[k]=(count,now);if(count>=(RequireConfirmations?2:1))Offer(new(Profile.Protocol,(int)tg,o.Source is uint radio?(int)radio:null,carrier.Hz,o.GrantSlot.Value,null,now,now,RequireConfirmations?"Repeated CRC-valid mapped group grant":"TENTATIVE CRC-valid mapped group grant",carrier.ColorCode),now);return;
        }
        if(frequency==ControlHz&&o.SystemType=="Capacity Plus"){if(capCc.HasValue&&capCc!=o.ColorCode){Stop(now,"Control color code changed; review selected system/profile");return;}capCc=o.ColorCode;}
        if(o.RestChannel is not (>0 and <=16) || o.SystemType is not("Capacity Plus" or "Motorola rest signaling")||frequency!=ControlHz)return;
        int rest=o.RestChannel.Value;if(restCandidate!=rest||(now-restAt).TotalSeconds>2){restCandidate=rest;restCount=0;}restAt=now;restCount++;
        var map=Profile.Carriers.FirstOrDefault(c=>c.Lcn==(rest+1)/2&&(c.Confirmed||!RequireConfirmations));if(map==null){Status=Active==null?$"Unresolved rest LSN {rest}; channel map required":Status;return;}
        if(restCount>=(RequireConfirmations?3:1)&&map.Hz!=ControlHz){ControlHz=map.Hz;Log(now,"Rest change",$"Rest LSN {rest}, {(map.Confirmed?"confirmed":"TENTATIVE")} LCN {(rest+1)/2}",ControlHz);restCount=0;}}
    internal void ObserveCap(CapStatus status,long source,DateTimeOffset now){if(!Running||Profile.Protocol!="Capacity Plus"||source!=ControlHz)return;foreach(var g in status.Groups){var map=Profile.Carriers.FirstOrDefault(c=>c.Lcn==(g.Lsn+1)/2&&(c.Confirmed||!RequireConfirmations));if(map==null){Log(now,"Unresolved",$"TG {g.Talkgroup} / LSN {g.Lsn} needs confirmed carrier LCN {(g.Lsn+1)/2}",0,g.Talkgroup);continue;}
        string key=$"grant:{g.Lsn}:{g.Talkgroup}";int n=candidates.TryGetValue(key,out var v)&&(now-v.Seen).TotalSeconds<=2?v.Count+1:1;if(candidates.Count>500)candidates.Clear();candidates[key]=(n,now);if(n>=(RequireConfirmations?2:1))Offer(new("Capacity Plus",g.Talkgroup,null,map.Hz,(g.Lsn-1)%2+1,null,now,now,(RequireConfirmations?"Repeated CRC-valid group status":"TENTATIVE single CRC-valid group status / optional map confirmation")+"; voice identity required before audio",map.ColorCode??capCc),now);}}
    internal void Voice(DateTimeOffset now){if(Active is {} a)Active=a with{Seen=now};}
    internal void End(DateTimeOffset now,string reason){if(Active is {} a){Log(now,"Call end",reason,a.Hz,a.Talkgroup,a.Slot,a.ColorCode,a.Radio,a.Nac);Active=null;Status="Returning to control/rest";}}
    internal void Tick(DateTimeOffset now){if(now>=nextPrune){nextPrune=now.AddSeconds(1);foreach(var k in candidates.Where(p=>(now-p.Value.Seen).TotalSeconds>15).Select(p=>p.Key).ToArray())candidates.Remove(k);foreach(var k in available.Where(p=>(now-p.Value.Seen).TotalSeconds>15).Select(p=>p.Key).ToArray())available.Remove(k);}if(Active is {} a&&((now-a.Seen).TotalSeconds>=HangSeconds||(now-a.First).TotalSeconds>=MaximumSeconds))End(now,"Hang/maximum timer");}
}
internal sealed record CapGroup(int Lsn,int Talkgroup);
internal sealed record CapStatus(int Rest,CapGroup[] Groups);
// CRC-validated vendor CSBK input; bounded assembly, never padded/truncated into an invented call.
internal sealed class CapStatusDecoder
{
    private readonly Dictionary<(int Slot,int Cc),(List<byte> Bytes,DateTimeOffset Time,int RestLsn)> pending=[];
    internal CapStatus? Feed(DmrObservation o,DateTimeOffset now){if(!o.LinkValid||o.SlotCorrections>1||o.DataType!=3||o.Slot is not(1 or 2))return null;byte[] p;try{p=Convert.FromHexString(o.Payload.Length>0?o.Payload:o.Raw);}catch{return null;}if(p.Length!=12||(p[0]&63)!=62||p[1]!=16||(p[0]&64)!=0||TrunkSignaling.Crc16(p.AsSpan(0,10))!=((p[10]<<8|p[11])^0xA5A5))return null;
        int flag=p[2]>>6,rest=p[2]&15;var key=(o.Slot.Value,o.ColorCode);if(flag is 2 or 3)pending[key]=(p.Take(10).ToList(),now,rest);else{if(!pending.TryGetValue(key,out var prev)||(now-prev.Time).TotalSeconds>1||prev.RestLsn!=rest||prev.Bytes.Count>=52){pending.Remove(key);return null;}prev.Bytes.AddRange(p.Skip(3).Take(7));pending[key]=(prev.Bytes,now,rest);}if(flag is 0 or 2)return null;var bytes=pending[key].Bytes;pending.Remove(key);return Parse(bytes.ToArray(),rest);}
    internal static CapStatus? Parse(byte[] bytes,int rest){if(bytes.Length<5)return null;var groups=new List<CapGroup>();int at=4;for(int bank=0;bank<2;bank++){int mask=bytes[at-1];for(int i=0;i<8;i++)if((mask&(128>>i))!=0){if(at>=bytes.Length)return null;int tg=bytes[at++];if(tg==0)return null;groups.Add(new(bank*8+i+1,tg));}if(bank==0){if(at>=bytes.Length)return null;at++;}}return new(rest,groups.ToArray());}
}
